func pPUNew(t *testing.T) *pPUH {
	t.Helper()
	h := &pPUH{t: t, tmp: t.TempDir(), clock: time.Date(2026, 10, 8, 15, 0, 0, 0, time.UTC)}
	h.state = filepath.Join(h.tmp, "state")
